package com.madar.files;
import org.json.*;
import java.io.IOException;
import java.util.*;
final class AgentTools {
 static final String FIELDS="format quality width height start end first last angle ratio targetKb compression ocrLanguage language target translationMode musicMode musicOutput separateSpeechMusic geminiReview cutBackground cutModel pdfTextMode bitrate color padding radius flip brightness contrast saturation speed volume fadeIn fadeOut scope documentMode normalize fade ocrOutput flipAxis qrValue qrType linkUrl linkMode linkQuality targetAspect aspectQuality";
 static List<String> tools(String kind){String names;switch(kind){case "image":names="convert crop compress resize background rotate ocr translateDocument imageBatch targetImage removebg adjust flip";break;case "video":names="convert trim compress resize mute audio music subtitles editor sound player";break;case "audio":names="subtitles convert trim sound music player";break;case "pdf":names="convert extract preview text word mergePdf imagesPdf protectPdf compressPdf layoutWord pages translateDocument";break;default:names="";}List<String> out=new ArrayList<>(Arrays.asList(names.split(" ")));out.remove("");out.addAll(Arrays.asList("ask","chat","history","deleteRecent","qr","downloadLink"));return out;}
 /** Clear document commands should not depend on a small model guessing a tool name. */
 static JSONObject explicitDocument(String user,String kind)throws Exception{
  if(!kind.equals("pdf"))return null;
  String text=java.text.Normalizer.normalize(user,java.text.Normalizer.Form.NFKC).toLowerCase(Locale.ROOT).replaceAll("[\\u064b-\\u065f\\u0670]","").replaceAll("[أإآ]","ا").trim();
  if(text.matches("(?s).*[\\p{N}].*")||text.matches("(?s).*(كيف|لماذا|ليش|وش|ماهو|ماهي|هل|اشرح|شرح|تعريف|معنى|طريقة|طريقه|اعرف|فائده|الفرق|بدون|بعدين|بعدها|ثم|ترجم|ترجمه|translate|rotate|احذف|امسح|ادمج|merge|delete|قص|split|png|jpg|جيميناي|gemini|colab|كولاب).*"))return null;
  if(java.util.regex.Pattern.compile("(?:^|\\s)(?:لا|لات|مو|ليس|not|dont|don't)(?:\\s|$)|(?:^|\\s)لا\\s*(?:تحول|تغير|تسوي)|ما\\s*(?:ابي|ابغ|اريد)").matcher(text).find())return null;
  if(!java.util.regex.Pattern.compile("(?<![\\p{L}])(?:للو?ورد|لو?ورد|وورد|word|docx)(?![\\p{L}])").matcher(text).find())return null;
  boolean action=java.util.regex.Pattern.compile("حول|تحويل|خلي|ابغ|ابي|اريد|سوي|جهز|اجعل|انشئ|صدر|convert|make|export").matcher(text).find()||text.matches("^(?:وورد|word|docx)(?:\\s.*)?$");if(!action)return null;
  String tool=java.util.regex.Pattern.compile("نص فقط|النص فقط|نص عادي|plain text|text only").matcher(text).find()?"word":"layoutWord";
  return new JSONObject().put("tool",tool).put("fields",new JSONArray()).put("message","");
 }
 static JSONObject actionsSchema()throws JSONException{return new JSONObject("{\"type\":\"array\",\"maxItems\":8,\"items\":{\"type\":\"object\",\"properties\":{\"action\":{\"type\":\"string\",\"enum\":[\"trim\",\"remove\",\"addText\",\"addImage\",\"addMusic\",\"silence\",\"enhance\",\"export\"]},\"start\":{\"type\":\"number\"},\"end\":{\"type\":\"number\"},\"text\":{\"type\":\"string\"},\"volume\":{\"type\":\"number\"}},\"required\":[\"action\"],\"additionalProperties\":false}}");}
 static JSONObject schemaBase(String kind)throws JSONException {return new JSONObject().put("type","object").put("properties",new JSONObject().put("tool",new JSONObject().put("type","string").put("enum",new JSONArray(tools(kind)))).put("fields",new JSONObject().put("type","array").put("items",new JSONObject().put("type","object").put("properties",new JSONObject().put("name",new JSONObject().put("type","string").put("enum",new JSONArray(Arrays.asList(FIELDS.split(" "))))).put("value",new JSONObject().put("type","string"))).put("required",new JSONArray(Arrays.asList("name","value"))).put("additionalProperties",false))).put("message",new JSONObject().put("type","string")).put("actions",actionsSchema())).put("required",new JSONArray(Arrays.asList("tool","fields","message"))).put("additionalProperties",false);}
 static JSONObject schema(String kind)throws Exception{JSONObject schema=schemaBase(kind);schema.getJSONObject("properties").put("steps",new JSONObject().put("type","array").put("maxItems",4).put("items",AgentWorkflow.stepSchema()));return schema;}
 static JSONObject validate(JSONObject plan,String kind)throws Exception {if(!tools(kind).contains(plan.getString("tool")))throw new IOException("اقترح المساعد أداة غير متاحة لهذا الملف");String message=plan.getString("message");if(message.length()>1000)throw new IOException("رد المساعد أطول من الحد");JSONArray fields=plan.getJSONArray("fields");if(fields.length()>12)throw new IOException("إعدادات المساعد كثيرة؛ اطلب عملية واحدة");JSONArray actions=plan.optJSONArray("actions");if(actions!=null){if(!plan.getString("tool").equals("editor")&&actions.length()>0)throw new IOException("عمليات المونتاج تحتاج ملف فيديو");if(actions.length()>8)throw new IOException("الحد ثماني خطوات في طلب المونتاج");for(int i=0;i<actions.length();i++){JSONObject action=actions.getJSONObject(i);String name=action.getString("action");if(!Arrays.asList("trim","remove","addText","addImage","addMusic","silence","enhance","export").contains(name))throw new IOException("عملية مونتاج غير مدعومة");for(Iterator<String> keys=action.keys();keys.hasNext();){String key=keys.next();if(!Arrays.asList("action","start","end","text","volume").contains(key))throw new IOException("إعداد مونتاج غير مدعوم");}for(String key:new String[]{"start","end","volume"})if(action.has(key)){Object n=action.get(key);if(!(n instanceof Number)||!Double.isFinite(((Number)n).doubleValue())||((Number)n).doubleValue()<0||((Number)n).doubleValue()>(key.equals("volume")?200:86400))throw new IOException("وقت أو مستوى صوت غير صالح");}if(action.optString("text").length()>1000)throw new IOException("اختصر نص العنصر");if(Arrays.asList("trim","remove","addText","addImage","addMusic").contains(name)&&(!action.has("start")||!action.has("end")||action.getDouble("end")<=action.getDouble("start")))throw new IOException("حدد بداية ونهاية واضحة للعملية");}}Set<String> seen=new HashSet<>();for(int i=0;i<fields.length();i++){JSONObject f=fields.getJSONObject(i);String name=f.getString("name"),value=f.getString("value");if(!Arrays.asList(FIELDS.split(" ")).contains(name)||!seen.add(name)||value.length()>((name.equals("qrValue")||name.equals("linkUrl"))?1800:100)||(name.equals("qrValue")?value.replace("\n","").replace("\r","").replace("\t",""):value).matches("(?s).*[\\p{Cntrl}].*"))throw new IOException("إعداد مقترح غير صالح");}if(Arrays.asList("ask","chat","history").contains(plan.getString("tool"))&&fields.length()!=0)throw new IOException("هذا الرد لا يحتاج إعدادات");
 if(plan.getString("tool").equals("deleteRecent")){for(int i=0;i<fields.length();i++){JSONObject field=fields.getJSONObject(i);if(!field.getString("name").equals("scope")||!Arrays.asList("latest","all").contains(field.getString("value")))throw new IOException("نطاق حذف غير صالح");}}AgentWorkflow.validate(plan,kind);return plan;}
}
